def call_tool(name: str, args: dict | None = None) -> Any:
    if args is None:
        args = {}
    if not isinstance(args, dict):
        raise InputError("TOOL_ARGUMENTS_INVALID", "Argumentos da ferramenta inválidos.", "Invalid tool arguments.")
    allowed = {"search_policies": {"query", "locale"}, "get_case_preview": {"id"}, "list_cases": set()}
    if not isinstance(name, str) or name not in allowed:
        raise InputError("TOOL_NOT_ALLOWED", "Esta ferramenta não está disponível. Somente leitura é permitida.", "This tool is unavailable. Only read operations are allowed.")
    if set(args) - allowed[name]:
        raise InputError("TOOL_ARGUMENTS_INVALID", "Campo não permitido na ferramenta.", "Unexpected tool argument.")
    if name == "search_policies":
        return {"source": "synthetic-policies", "retrieval": "lexical", "results": retrieve_policy(args.get("query"), args.get("locale", "pt"))}
    if name == "list_cases":
        return [{**{key: row[key] for key in ("id", "locale", "expectedAction", "expectedCategory")}, "synthetic": True} for row in EVALUATION]
    if not isinstance(args.get("id"), str) or not 1 <= len(args["id"]) <= 80:
        raise InputError("TOOL_ARGUMENTS_INVALID", "Use um identificador de 1 a 80 caracteres.", "Use an identifier of 1–80 characters.")
    row = next((row for row in EVALUATION if row["id"] == args.get("id")), None)
    if row is None:
        raise InputError("CASE_NOT_FOUND", "Caso sintético não encontrado.", "Synthetic case not found.")
    return {**row, "synthetic": True, "result": moderate(row)}


def evaluate_dataset() -> dict:
    rows = []
    for row in EVALUATION:
        reference = moderate({**row, "mode": "reference"})
        proposed = moderate({**row, "mode": "proposed"})
        rows.append({**row, "reference": reference, "proposed": proposed,
                     "referencePass": reference["action"] == row["expectedAction"] and reference["category"] == row["expectedCategory"],
                     "proposedPass": proposed["action"] == row["expectedAction"] and proposed["category"] == row["expectedCategory"]})

    def summarize(mode: str) -> dict:
        correct = sum(row[f"{mode}Pass"] for row in rows)
        review_count = sum(row[mode]["action"] in ("review", "hold") for row in rows)
        allowed = [row for row in rows if row["expectedAction"] == "allow"]
        risky = [row for row in rows if row["expectedAction"] != "allow"]
        fp = sum(row[mode]["action"] != "allow" for row in allowed)
        fn = sum(row[mode]["action"] == "allow" for row in risky)
        latencies = sorted(row[mode]["simulatedLatencyMs"] for row in rows)
        return {"correct": correct, "total": len(rows), "accuracy": correct / len(rows), "reviewCount": review_count, "reviewRate": review_count / len(rows), "falsePositiveCount": fp, "falsePositiveRate": fp / len(allowed), "falseNegativeCount": fn, "falseNegativeRate": fn / len(risky), "simulatedP95LatencyMs": latencies[math.ceil(len(rows) * 0.95) - 1], "simulatedTotalCostUsd": round(sum(row[mode]["simulatedCostUsd"] for row in rows), 6)}

    return {"dataset": "synthetic-fixtures-v1", "engineVersion": ENGINE_VERSION, "synthetic": True, "total": len(rows), "rows": rows, "reference": summarize("reference"), "proposed": summarize("proposed"), "disclaimer": {"pt": "Acurácia mede concordância com 18 exemplos sintéticos escritos pelo autor. Latência e custo são cenários fixos, não medições. Não é um benchmark independente.", "en": "Accuracy measures agreement with 18 author-written synthetic examples. Latency and cost are fixed scenarios, not measurements. This is not an independent benchmark."}}

"""Small MCP 2025-03-26 stdio server using the standard library only.

Supports lifecycle, ping and three read-only tools. No sampling, mutation tools,
HTTP transport, secrets or external I/O. Stdout contains JSON-RPC messages only.
"""
from __future__ import annotations

import json
import sys
from typing import Any

from .engine import TOOL_DEFINITIONS, InputError, call_tool

PROTOCOL_VERSION = "2025-03-26"
MAX_LINE_BYTES = 16384


class Session:
    def __init__(self):
        self.initialized = False
        self.ready = False

    @staticmethod
    def error(identifier, code: int, message: str) -> dict:
        return {"jsonrpc": "2.0", "id": identifier, "error": {"code": code, "message": message}}

    def dispatch(self, request: Any) -> dict | list | None:
        if isinstance(request, list):
            if not request or len(request) > 20:
                return self.error(None, -32600, "Invalid batch")
            if any(isinstance(item, dict) and item.get("method") == "initialize" for item in request):
                return self.error(None, -32600, "Initialization cannot be batched")
            responses = [self.dispatch(item) for item in request]
            return [response for response in responses if response is not None] or None
        if not isinstance(request, dict) or request.get("jsonrpc") != "2.0" or not isinstance(request.get("method"), str):
            return self.error(None, -32600, "Invalid request")
        identifier = request.get("id")
        if "id" in request and (isinstance(identifier, bool) or not isinstance(identifier, (str, int))):
            return self.error(None, -32600, "Invalid request id")
        method, params = request["method"], request.get("params", {})
        if "id" not in request:
            if method == "notifications/initialized" and self.initialized:
                self.ready = True
            return None
        if not isinstance(params, dict):
            return self.error(identifier, -32602, "Parameters must be an object")
        if method == "initialize":
            if self.initialized:
                return self.error(identifier, -32600, "Already initialized")
            if not isinstance(params.get("protocolVersion"), str) or not isinstance(params.get("clientInfo"), dict) or not isinstance(params.get("capabilities"), dict):
                return self.error(identifier, -32602, "Missing initialization fields")
            self.initialized = True
            result = {"protocolVersion": PROTOCOL_VERSION, "capabilities": {"tools": {"listChanged": False}}, "serverInfo": {"name": "safechat-synthetic-demo", "version": "1.0.0"}, "instructions": "Fictional policies and synthetic cases only. All tools are read-only. No account actions exist."}
        elif method == "ping":
            result = {}
        elif not self.ready:
            return self.error(identifier, -32002, "Initialize and send notifications/initialized first")
        elif method == "tools/list":
            if params.get("cursor") is not None:
                return self.error(identifier, -32602, "Pagination cursor is unsupported for this fixed tool list")
            result = {"tools": TOOL_DEFINITIONS}
        elif method == "tools/call":
            try:
                output = call_tool(params.get("name"), params.get("arguments", {}))
                result = {"content": [{"type": "text", "text": json.dumps(output, ensure_ascii=False)}], "isError": False}
            except InputError as error:
                if error.code in ("TOOL_NOT_ALLOWED", "TOOL_ARGUMENTS_INVALID", "QUERY_INVALID", "LOCALE_INVALID"):
                    return self.error(identifier, -32602, error.code)
                result = {"content": [{"type": "text", "text": json.dumps(error.as_dict(), ensure_ascii=False)}], "isError": True}
        else:
            return self.error(identifier, -32601, "Method not found")
        return {"jsonrpc": "2.0", "id": identifier, "result": result}


def main() -> None:
    session = Session()
    while True:
        line = sys.stdin.buffer.readline(MAX_LINE_BYTES + 1)
        if not line:
            break
        if len(line) > MAX_LINE_BYTES:
            # Drain the oversized frame without loading it into memory.
            while line and not line.endswith(b"\n"):
                line = sys.stdin.buffer.readline(MAX_LINE_BYTES + 1)
            response = session.error(None, -32600, "Frame exceeds 16 KiB")
        else:
            try:
                response = session.dispatch(json.loads(line))
            except (json.JSONDecodeError, UnicodeDecodeError):
                response = session.error(None, -32700, "Parse error")
        if response is not None:
            sys.stdout.write(json.dumps(response, ensure_ascii=False, separators=(",", ":")) + "\n")
            sys.stdout.flush()


if __name__ == "__main__":
    main()

"""Opt-in local Ollama advice. Never used by moderation or policy authority.

Only loopback HTTP is supported; no credentials, tools, redirects or environment
proxies. Tests use MockTransport and never contact a model. Provider output is
untrusted even after schema validation. No raw provider response is logged.
"""
from __future__ import annotations

import asyncio
import json
import os
from dataclasses import dataclass
from typing import Literal
from urllib.parse import urlsplit

import httpx
